import sys,lzma,bz2
T=[(4,0,0),(0,0,0),(1,0,0),(3,0,0),(2,0,0)]
def F(lc,lp,pb):
    return [{"id":lzma.FILTER_LZMA2,"preset":9|lzma.PRESET_EXTREME,"lc":lc,"lp":lp,"pb":pb,"dict_size":1<<24}]
def main():
    m=sys.argv[1];d=sys.stdin.buffer.read();o=sys.stdout.buffer
    if m=='c':
        c=[b'\x09'+d,b'\0'+bz2.compress(d,9)]
        for i,(lc,lp,pb) in enumerate(T):
            c.append(bytes([1+i])+lzma.compress(d,format=lzma.FORMAT_RAW,filters=F(lc,lp,pb)))
        o.write(min(c,key=len))
    else:
        t=d[0];b=d[1:]
        if t==0:r=bz2.decompress(b)
        elif t==9:r=b
        else:
            lc,lp,pb=T[t-1]
            r=lzma.decompress(b,format=lzma.FORMAT_RAW,filters=F(lc,lp,pb))
        o.write(r)
main()
